function.arguments:
{"code": "all_recommendations = []
page_index = 0
page_limit = 20
while True:
    recommendations = apis.spotify.show_recommendations(access_token=token, page_index=page_index, page_limit=page_limit)
    if not recommendations:
        break
    all_recommendations.extend(recommendations)
    page_index += 1

artist_counts = {}
for song in all_recommendations:
    for artist in song['artists']:
        artist_name = artist['name']
        artist_counts[artist_name] = artist_counts.get(artist_name, 0) + 1

least_recommended_artists = [k for k, v in artist_counts.items() if v == min(artist_counts.values())]
print(least_recommended_artists)"}

