actions.command:
# Step 3: Collect unique artist IDs from liked songs
artist_ids = set()
for song in liked_songs:
    for artist in song['artists']:
        artist_ids.add(artist['id'])

# Step 4: Follow each unique artist
for artist_id in artist_ids:
    apis.spotify.follow_artist(access_token=spotify_token, artist_id=artist_id)

# Step 4: Check if already following each artist before following
for artist_id in artist_ids:
    following_status = apis.spotify.show_artist_following(
        access_token=spotify_token, 
        artist_id=artist_id
    )
    if not following_status.get('following', False):
        apis.spotify.follow_artist(
            access_token=spotify_token, 
            artist_id=artist_id
        )

