liked_song_ids = {song['song_id'] for song in liked_songs}
common_song_ids = downloaded_song_ids.intersection(liked_song_ids)
print(common_song_ids)

def get_all_pages(api_call, access_token, page_limit=20):
    all_results = []
    page_index = 0
    while True:
        response = api_call(access_token=access_token, page_index=page_index, page_limit=page_limit)
        if not response:
            break
        all_results.extend(response)
        page_index += 1
    return all_results

downloaded_songs = get_all_pages(apis.spotify.show_downloaded_songs, access_token=spotify_token)
liked_songs = get_all_pages(apis.spotify.show_liked_songs, access_token=spotify_token)

downloaded_song_ids = {song['song_id'] for song in downloaded_songs}
liked_song_ids = {song['song_id'] for song in liked_songs}
common_song_ids = downloaded_song_ids.intersection(liked_song_ids)
print(common_song_ids)

