actions.command:
album_songs = []
for album in all_albums:
    album_details = apis.spotify.show_album(access_token=token, album_id=album['album_id'])
    album_artists = album_details.get('artists', [])
    if 'songs' in album_details:
        for song in album_details['songs']:
            song_id = song.get('id')
            title = song.get('title')
            song_artists = album_artists
            album_songs.append({
                'song_id': song_id,
                'title': title,
                'artists': song_artists
            })
print(f"Reprocessed album_songs: {album_songs}")

song_ids = set()

for song in all_songs:
    song_ids.add(song['song_id'])

for song in album_songs:
    song_ids.add(song['song_id'])

for playlist in all_playlists:
    song_ids.update(playlist['song_ids'])

print(f"Total unique song IDs to process: {len(song_ids)}")

