actions.command:
unique_song_ids = set()
for playlist in playlists_page_0:
    unique_song_ids.update(playlist['song_ids'])

classical_artists = set()
for song_id in unique_song_ids:
    song = apis.spotify.show_song(access_token=token, song_id=song_id)
    if song['genre'] == 'classical':
        for artist in song['artists']:
            classical_artists.add(artist['id'])

print(classical_artists)

following_response = apis.spotify.show_following_artists(access_token=token)
followed_artists = {artist['id'] for artist in following_response}
new_artists_to_follow = classical_artists - followed_artists

for artist_id in new_artists_to_follow:
    apis.spotify.follow_artist(access_token=token, artist_id=artist_id)

following_response = apis.spotify.show_following_artists(access_token=token)
followed_artists = {artist['artist_id'] for artist in following_response}
new_artists_to_follow = classical_artists - followed_artists

for artist_id in new_artists_to_follow:
    apis.spotify.follow_artist(access_token=token, artist_id=artist_id)

