actions.command:
import os

target_dir = "/home/paul/photographs/vacations/"
petra_dir = f"{target_dir}Petra"
budapest_dir = f"{target_dir}Budapest"
amsterdam_dir = f"{target_dir}Amsterdam"

for entry in directory_contents:
    if entry.startswith(target_dir) and (entry.endswith('.jpg') or entry.endswith('.jpeg') or entry.endswith('.png')):
        # Skip directories created for organization
        if any(entry.startswith(dest_dir) for dest_dir in [petra_dir, budapest_dir, amsterdam_dir]):
            continue

        try:
            metadata = apis.file_system.show_file(file_path=entry, access_token=access_token)
            created_at = metadata['created_at']
            year, month = created_at.split('T')[0].split('-')[:2]

            if year == '2023' and month == '02':
                dest_dir = petra_dir
            elif year == '2023' and month == '03':
                dest_dir = budapest_dir
            else:
                dest_dir = amsterdam_dir

            file_name = os.path.basename(entry)
            destination_path = f"{dest_dir}/{file_name}"

            apis.file_system.move_file(source_path=entry, destination_path=destination_path, access_token=access_token)
            print(f"Moved {entry} to {destination_path}")

        except Exception as e:
            print(f"Error processing {entry}: {e}")

