actions.command:
# Step 14: Like all songs in the queue up to and including the current song
current_position = next(song['position'] for song in song_queue if song['is_current'])
for song in song_queue:
    if song['position'] <= current_position:
        song_id = song['song_id']
        apis.spotify.like_song(song_id=song_id, access_token=token)

